svg.script:
(function () {
  var root = document.getElementById('a16p15-svg');
  if (!root) {
    var all = document.getElementsByClassName('a16p15-root');
    root = all && all[0] ? all[0] : null;
  }
  if (!root) return;

  var stepIds = ['a16p15-btn-caso', 'a16p15-btn-rastreio', 'a16p15-btn-invasivo'];
  var consentBtn = document.getElementById('a16p15-consent');
  var consentLabel = document.getElementById('a16p15-consent-label');
  var consentSub = document.getElementById('a16p15-consent-sub');
  var verdictMain = document.getElementById('a16p15-verdict-main');
  var verdictSub = document.getElementById('a16p15-verdict-sub');
  var tooltip = document.getElementById('a16p15-tooltip');
  var tipTitle = document.getElementById('a16p15-tip-title');
  var tipBody = document.getElementById('a16p15-tip-body');
  var tipBg = document.getElementById('a16p15-tip-bg');

  var verdicts = {
    caso: { main: 'TN = risco', sub: 'não fecha cariótipo' },
    rastreio: { main: 'Oferecer rastreio', sub: 'biofís · bioquím · NIPT' },
    invasivo: { main: 'Só se aceito', sub: 'BVC 10–13 ou amnio' }
  };

  function clearActive(ids) {
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) el.classList.remove('a16p15-active');
    }
  }

  function setStep(step) {
    var s = step || 'caso';
    root.setAttribute('data-step', s);
    clearActive(stepIds);
    for (var i = 0; i < stepIds.length; i++) {
      var btn = document.getElementById(stepIds[i]);
      if (btn && btn.getAttribute('data-step') === s) btn.classList.add('a16p15-active');
    }
    var v = verdicts[s] || verdicts.caso;
    if (verdictMain) verdictMain.textContent = v.main;
    if (verdictSub) verdictSub.textContent = v.sub;
    refreshConsentCopy();
  }

  function getConsent() {
    return root.getAttribute('data-consent') || 'locked';
  }

  function refreshConsentCopy() {
    var c = getConsent();
    if (!consentLabel || !consentSub) return;
    if (c === 'open') {
      consentLabel.textContent = 'ACEITO';
      consentSub.textContent = 'porta aberta · BVC/amnio';
      if (root.getAttribute('data-step') === 'invasivo') {
        if (verdictMain) verdictMain.textContent = 'Invasivo liberado';
        if (verdictSub) verdictSub.textContent = 'BVC agora ou amnio depois';
      }
    } else if (c === 'refused') {
      consentLabel.textContent = 'RECUSADO';
      consentSub.textContent = 'fica no rastreio';
      if (root.getAttribute('data-step') === 'invasivo') {
        if (verdictMain) verdictMain.textContent = 'Sem invasivo';
        if (verdictSub) verdictSub.textContent = 'autonomia · permanece rastreio';
      }
    } else {
      consentLabel.textContent = 'CONSENTIMENTO';
      consentSub.textContent = 'toque: aceitar / recusar';
      if (root.getAttribute('data-step') === 'invasivo') {
        var v = verdicts.invasivo;
        if (verdictMain) verdictMain.textContent = v.main;
        if (verdictSub) verdictSub.textContent = v.sub;
      }
    }
  }

  function cycleConsent() {
    var c = getConsent();
    var next = 'locked';
    if (c === 'locked') next = 'open';
    else if (c === 'open') next = 'refused';
    else next = 'locked';
    root.setAttribute('data-consent', next);
    if (root.getAttribute('data-step') !== 'invasivo') {
      setStep('invasivo');
    } else {
      refreshConsentCopy();
    }
  }

  function bindStep(id) {
    var el = document.getElementById(id);
    if (!el) return;
    var run = function () { setStep(el.getAttribute('data-step') || 'caso'); };
    el.addEventListener('click', run);
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); run(); }
    });
  }

  for (var s = 0; s < stepIds.length; s++) bindStep(stepIds[s]);

  if (consentBtn) {
    consentBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      cycleConsent();
    });
    consentBtn.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        cycleConsent();
      }
    });
  }

  function wrapBody(text, maxChars) {
    var words = (text || '').split(/\s+/);
    var lines = [];
    var cur = '';
    for (var i = 0; i < words.length; i++) {
      var trial = cur ? cur + ' ' + words[i] : words[i];
      if (trial.length > maxChars && cur) {
        lines.push(cur);
        cur = words[i];
      } else {
        cur = trial;
      }
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 3);
  }

  function showTip(title, body, clientX, clientY) {
    if (!tooltip || !tipTitle || !tipBody) return;
    tipTitle.textContent = title || '';
    while (tipBody.firstChild) tipBody.removeChild(tipBody.firstChild);
    var lines = wrapBody(body, 42);
    for (var i = 0; i < lines.length; i++) {
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      t.setAttribute('x', '12');
      t.setAttribute('dy', i === 0 ? '0' : '14');
      t.textContent = lines[i];
      tipBody.appendChild(t);
    }
    var th = 36 + Math.max(1, lines.length) * 14;
    if (tipBg) {
      tipBg.setAttribute('width', '280');
      tipBg.setAttribute('height', String(th));
    }
    tooltip.classList.add('a16p15-show');
    moveTip(clientX, clientY);
  }

  function moveTip(clientX, clientY) {
    if (!tooltip || !tooltip.classList.contains('a16p15-show')) return;
    var ctm = root.getScreenCTM();
    if (!ctm) return;
    var pt = root.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    var sp = pt.matrixTransform(ctm.inverse());
    var x = sp.x + 14;
    var y = sp.y + 14;
    var vb = root.viewBox.baseVal;
    var maxX = (vb && vb.width ? vb.width : 1000) - 292;
    var maxY = (vb && vb.height ? vb.height : 860) - 80;
    if (x > maxX) x = sp.x - 294;
    if (y > maxY) y = sp.y - 80;
    if (x < 8) x = 8;
    if (y < 8) y = 8;
    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
  }

  function hideTip() {
    if (tooltip) tooltip.classList.remove('a16p15-show');
  }

  var tips = root.querySelectorAll('[data-tip-title]');
  for (var t = 0; t < tips.length; t++) {
    (function (el) {
      el.addEventListener('mouseenter', function (e) {
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), e.clientX, e.clientY);
      });
      el.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });
      el.addEventListener('mouseleave', hideTip);
      el.addEventListener('focus', function () {
        var r = el.getBoundingClientRect();
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), r.left + r.width / 2, r.top);
      });
      el.addEventListener('blur', hideTip);
    })(tips[t]);
  }

  root.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });

  setStep('caso');
  root.setAttribute('data-consent', 'locked');
  refreshConsentCopy();
})();
